        SV2 = SV2*2
        p_top(:) = qext(6,:) + qext(7,:) + qext(3,:) ! Tbar > Bbar + W- (6,7)
        SV3 = p_top(1)**2 - p_top(2)**2 - p_top(3)**2 - p_top(4)**2

	call abbr0_s

	result(1) = 0
	result(2) = 0

C Warning: helicity order Hel1 (Dbar), Hel2 (photon), Hel3 (Ubar), 
C Hel4 (W+), Hel5 (Z), Hel6 (T), Hel7 (e+), Hel8 (nue), Hel9 (mu+), Hel10 (mu-)
	Hel1 = 1 ! initial anti quark (only right-handed)
        Hel6 = Hel1 ! for anti-b quark (only right-handed)

	Hel7 = 1 ! final e+
	Hel8 = -1 ! final nue

	Hel9 = -1 ! lepton 3
	Hel10 = -Hel9 ! lepton 4
       DO Hel2 = -1, 1, 2 ! initial photon
***[for qq->W+V*Br(W+)*Br(V)
        Ctree1(1) = 0

