        do Hel5 = hel_Z_min, hel_Z_max, hel_Z_step ! for V2=Wm
	do Hel3 = -1, 1, 2 ! anti-top quark (= anti-b + Wm), left only ?

	call abbr0_hel
	Ctree(1) = 0
	call born
        CtreeVV(1) = Ctree(1)

        call decayWll(ampW, 4, 7, 8) ! Wp
        call decayWmll(ampWm, 5, 9, 10)
        call decayTbar_BbarWm(ampT, 3, 6, 5) ! Tbar > Bbar + W-

c          print*,"hel 789", Hel7, Hel8, Hel9, Hel10, ampW, ampWm, ampT

        temp = -CtreeVV(1)*ampT*ampW*ampWm
     &  /((SV1 - CMWsq)*(SV2 - CMWsq)*(SV3 - CMTsq))

        Ctree1(1) = Ctree1(1) + temp

        enddo
        enddo
        enddo
***]for qq->W+V*Br(W+)*Br(V)

	result(1) = result(1) + sumup(Ctree1, Ctree1)

       ENDDO

c#define CHECK
#ifdef CHECK
        print*,"squaredme Bbarglu-fin-TW: sel hel T Bbar+"
	print *, 'S =', S
	print *, 'T =', T
	print *, 'U =', U

	print *, 'tree =', result(1)
	print *, 'loop =', result(2)
	stop
#endif
	end

************************************************************************

	double precision function sumup(CCloop, CCtree)
	implicit none

#include "vars.h"

	double complex CCloop(1), CCtree(1)
	double complex m

	sumup = 0

	m = 0
	m = m + CCloop(1)*MatSUN(1,1)
	sumup = sumup + DBLE(DCONJG(CCtree(1))*m)
	end
